import * as React from "react"
import {
  Label,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Switch,
} from "@invana/forms"
import {
  Badge,
  BoundChip,
  Button,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  ToggleGroup,
  ToggleGroupItem,
} from "@invana/ui"

import type { ActionContext, ActionSpec, ChipSpec } from "./types"

/** A chip from its spec — a bound renders as a `BoundChip`, everything else as a `Badge`. */
export function SpecChip({ chip }: { chip: ChipSpec }) {
  if (chip.bound)
    return <BoundChip bound={chip.bound} swatch={chip.swatch} />
  return (
    <Badge
      variant={chip.variant ?? "outline"}
      tone={chip.tone === "running" || chip.tone === "error" ? undefined : chip.tone}
      size="sm"
    >
      {chip.label}
    </Badge>
  )
}

export function SpecChips({ chips }: { chips?: ChipSpec[] }) {
  if (!chips?.length) return null
  return (
    <>
      {chips.map((chip, i) => (
        <SpecChip key={i} chip={chip} />
      ))}
    </>
  )
}

/**
 * An action from its spec.
 *
 * `options` turns it into a segmented switch, because a view switch is one
 * decision with several positions and rendering it as three buttons would let a
 * reader think they could pick two. `picker` draws the same choice as a
 * dropdown, for records too many or too long to lay side by side. `menu` puts
 * them behind the action's own button, as acts rather than a choice.
 */
export function SpecAction({
  action,
  onAction,
  icons,
  ctx,
}: {
  action: ActionSpec
  onAction: (id: string, ctx?: ActionContext) => void
  icons: Record<string, React.ComponentType<{ className?: string }>>
  ctx?: ActionContext
}) {
  const switchId = React.useId()
  const optionLabel = (option: string) => action.optionLabels?.[option] ?? option
  if (action.options?.length && action.menu) {
    const Trigger = action.icon ? icons[action.icon] : undefined
    return (
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          {/* With an icon the label names the button rather than printing
              beside it — `⋯` is read as *More*, not drawn as it. */}
          <Button
            variant={action.variant ?? "outline"}
            size={Trigger ? "icon-sm" : "sm"}
            disabled={action.disabled}
            aria-label={action.label ?? action.id}
          >
            {Trigger ? <Trigger /> : action.label}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {action.options.map((option) => (
            <DropdownMenuItem key={option} onSelect={() => onAction(action.id, { ...ctx, option })}>
              {optionLabel(option)}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }
  if (action.options?.length && action.picker) {
    return (
      <Select
        value={action.value}
        disabled={action.disabled}
        onValueChange={(option: string) => onAction(action.id, { ...ctx, option })}
      >
        <SelectTrigger triggerSize="sm" className="w-auto gap-2" aria-label={action.label ?? action.id}>
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {action.options.map((option) => (
            <SelectItem key={option} value={option}>
              {optionLabel(option)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    )
  }
  if (action.options?.length) {
    return (
      <ToggleGroup
        type="single"
        size="sm"
        value={action.value}
        disabled={action.disabled}
        onValueChange={(option: string) => option && onAction(action.id, { ...ctx, option })}
      >
        {action.options.map((option) => (
          <ToggleGroupItem key={option} value={option}>
            {optionLabel(option)}
          </ToggleGroupItem>
        ))}
      </ToggleGroup>
    )
  }

  const Icon = action.icon ? icons[action.icon] : undefined
  const iconOnly = !action.label && Icon

  if (action.pressed != null) {
    return (
      <span className="flex items-center gap-1.5">
        <Label htmlFor={switchId} className="font-normal">
          {action.label ?? action.id}
        </Label>
        <Switch
          id={switchId}
          checked={action.pressed}
          disabled={action.disabled}
          onCheckedChange={(pressed: boolean) => onAction(action.id, { ...ctx, pressed })}
        />
      </span>
    )
  }

  return (
    <Button
      variant={action.variant ?? "outline"}
      size={iconOnly ? "icon-sm" : "sm"}
      disabled={action.disabled}
      aria-label={iconOnly ? action.id : undefined}
      onClick={() => onAction(action.id, ctx)}
    >
      {Icon ? <Icon /> : null}
      {action.label}
    </Button>
  )
}

export function SpecActions({
  actions,
  onAction,
  icons,
  ctx,
}: {
  actions?: ActionSpec[]
  onAction: (id: string, ctx?: ActionContext) => void
  icons: Record<string, React.ComponentType<{ className?: string }>>
  ctx?: ActionContext
}) {
  if (!actions?.length) return null
  return (
    <>
      {actions.map((action) => (
        <SpecAction
          key={action.id}
          action={action}
          onAction={onAction}
          icons={icons}
          ctx={ctx}
        />
      ))}
    </>
  )
}
